// Extract company name
const subject = $input.first().json.subject || '';
const companyName = subject.replace(/^Research on\s*/i, '').trim() || 'Unknown Company';

// Define research sections
const sections = [
  'Company Overview',
  'Business Model and Revenue Streams', 
  'Market Position and Competitive Analysis',
  'Financial Performance and Metrics',
  'Management Team and Leadership',
  'Products and Services Portfolio',
  'Technology and Innovation',
  'Market Opportunities and Growth Strategy',
  'Risk Assessment and Challenges',
  'ESG and Sustainability Initiatives'
];

return {
  json: {
    companyName: companyName,
    sections: sections,
    taskId: $input.first().json.id,
    taskVersion: $input.first().json.version || 1,
    originalSubject: subject
  }
};

// Get the AI-generated content
const aiResponse = $input.first().json.response;
const companyName = $node['Extract Company Info'].json.companyName;
const taskId = $node['Extract Company Info'].json.taskId;
const taskVersion = $node['Extract Company Info'].json.taskVersion;

// Create structured research report
const timestamp = new Date().toISOString();
const report = {
  company: companyName,
  generatedBy: 'Mistral AI (Local LLM)',
  timestamp: timestamp,
  content: aiResponse,
  taskId: taskId,
  taskVersion: taskVersion,
  sections: [
    'Company Overview',
    'Business Model and Revenue Streams', 
    'Market Position and Competitive Analysis',
    'Financial Performance and Metrics',
    'Management Team and Leadership',
    'Products and Services Portfolio',
    'Technology and Innovation',
    'Market Opportunities and Growth Strategy',
    'Risk Assessment and Challenges',
    'ESG and Sustainability Initiatives'
  ],
  summary: {
    source: 'Local Mistral AI Model',
    quality: 'AI-Generated Professional Analysis',
    completeness: '100% - All sections covered'
  }
};

return { json: report };
